import { defineFunction, fail } from "@relkit/app/functions";
import { z } from "@relkit/app/schema";
import { membershipRejected } from "../errors.js";
import { companyStatus, id, membership, staffRole } from "../schemas.js";

export default defineFunction({
  id: "companies.add-staff",
  input: z.object({
    company: z.object({ companyId: id, status: companyStatus }),
    userId: id,
    role: staffRole,
    existingMemberUserIds: z.array(id),
  }),
  output: membership,
  errors: [membershipRejected],
  handler: async ({ company: snapshot, userId, role, existingMemberUserIds }) => {
    if (snapshot.status !== "active") {
      return fail(membershipRejected, { reason: "company-inactive" });
    }
    if (existingMemberUserIds.includes(userId)) {
      return fail(membershipRejected, { reason: "already-member" });
    }
    return { companyId: snapshot.companyId, userId, role, status: "active" as const };
  },
});

