import { z } from "@relkit/app/schema";

export const id = z.string().min(1).max(100).refine((value) => value.trim() === value);
export const companyDetails = {
  companyId: id,
  legalName: z.string().min(2).max(200).refine((value) => value.trim().length >= 2),
  registrationNumber: id,
};
export const companyStatus = z.union([z.literal("active"), z.literal("suspended")]);
export const staffRole = z.union([
  z.literal("admin"), z.literal("dispatcher"), z.literal("driver"), z.literal("mechanic"),
]);
export const company = z.object({
  ...companyDetails,
  status: companyStatus,
});
export const membership = z.object({
  companyId: id,
  userId: id,
  role: z.union([z.literal("owner"), staffRole]),
  status: z.union([z.literal("active"), z.literal("inactive")]),
});

