import { defineFunction, fail } from "@relkit/app/functions";
import { z } from "@relkit/app/schema";
import { registrationRejected } from "../errors.js";
import { driver, id, timestampMs } from "../schemas.js";

export default defineFunction({
  id: "fleet.register-driver",
  input: z.object({
    companyId: id,
    driverId: id,
    membership: z.object({
      companyId: id,
      userId: id,
      role: z.union([
        z.literal("owner"), z.literal("admin"), z.literal("dispatcher"),
        z.literal("driver"), z.literal("mechanic"),
      ]),
      status: z.union([z.literal("active"), z.literal("inactive")]),
    }),
    licenseValidUntilMs: timestampMs,
    nowMs: timestampMs,
  }),
  output: driver,
  errors: [registrationRejected],
  handler: async ({ companyId, driverId, membership, licenseValidUntilMs, nowMs }) => {
    if (membership.companyId !== companyId) {
      return fail(registrationRejected, { reason: "foreign-membership" });
    }
    if (membership.role !== "driver" || membership.status !== "active") {
      return fail(registrationRejected, { reason: "ineligible-membership" });
    }
    if (licenseValidUntilMs <= nowMs) {
      return fail(registrationRejected, { reason: "expired-license" });
    }
    return {
      companyId,
      driverId,
      userId: membership.userId,
      licenseValidUntilMs,
      active: true,
      availability: "available" as const,
    };
  },
});

