import { defineFunction, fail } from "@relkit/app/functions";
import { z } from "@relkit/app/schema";
import { maintenanceRejected } from "../errors.js";

const id = z.string().min(1).max(100).refine((value) => value.trim() === value);
const reading = z.number().int().nonnegative().max(Number.MAX_SAFE_INTEGER);
const recordFields = {
  companyId: id,
  recordId: id,
  odometerKm: reading,
  performedAtMs: reading,
  description: z.string().min(1).max(2_000).refine((value) => value.trim().length > 0),
};
const record = z.object({ ...recordFields, carId: id });

export default defineFunction({
  id: "maintenance.record-maintenance",
  input: z.object({
    ...recordFields,
    car: z.object({ companyId: id, carId: id, odometerKm: reading }),
    nowMs: reading,
  }),
  output: z.object({ record, proposedCarOdometerKm: reading }),
  errors: [maintenanceRejected],
  handler: async ({ car, nowMs, ...details }) => {
    if (details.companyId !== car.companyId) {
      return fail(maintenanceRejected, { reason: "foreign-car" });
    }
    if (details.odometerKm < car.odometerKm) {
      return fail(maintenanceRejected, { reason: "decreasing-odometer" });
    }
    if (details.performedAtMs > nowMs) {
      return fail(maintenanceRejected, { reason: "future-record" });
    }
    return {
      record: { ...details, carId: car.carId, description: details.description.trim() },
      proposedCarOdometerKm: details.odometerKm,
    };
  },
});

