import { defineFunction, fail } from "@relkit/app/functions";
import { z } from "@relkit/app/schema";
import { positionRejected } from "../errors.js";

const id = z.string().min(1).max(100).refine((value) => value.trim() === value);
const timestampMs = z.number().int().nonnegative().max(Number.MAX_SAFE_INTEGER);
const positionFields = {
  companyId: id,
  latitude: z.number().min(-90).max(90),
  longitude: z.number().min(-180).max(180),
  observedAtMs: timestampMs,
};

export default defineFunction({
  id: "tracking.validate-position",
  input: z.object({
    ...positionFields,
    car: z.object({ companyId: id, carId: id }),
    nowMs: timestampMs,
  }),
  output: z.object({ ...positionFields, carId: id, ageMs: timestampMs }),
  errors: [positionRejected],
  handler: async ({ car, nowMs, ...sample }) => {
    if (sample.companyId !== car.companyId) return fail(positionRejected, { reason: "foreign-car" });
    const ageMs = nowMs - sample.observedAtMs;
    if (ageMs < 0) return fail(positionRejected, { reason: "future-sample" });
    if (ageMs > 60_000) return fail(positionRejected, { reason: "stale-sample" });
    return { ...sample, carId: car.carId, ageMs };
  },
});

