import { defineFunction, fail } from "@relkit/app/functions";
import { z } from "@relkit/app/schema";
import { tripRejected } from "../errors.js";
import { id, timestampMs, trip } from "../schemas.js";

export default defineFunction({
  id: "trips.assign-trip",
  input: z.object({
    companyId: id,
    trip,
    car: z.object({
      companyId: id,
      carId: id,
      seats: z.number().int().min(1).max(100),
      availability: z.union([
        z.literal("available"), z.literal("reserved"), z.literal("in_trip"), z.literal("in_maintenance"),
      ]),
    }),
    driver: z.object({
      companyId: id,
      driverId: id,
      active: z.boolean(),
      availability: z.union([z.literal("available"), z.literal("reserved"), z.literal("in_trip")]),
      licenseValidUntilMs: timestampMs,
    }),
    nowMs: timestampMs,
  }),
  output: trip,
  errors: [tripRejected],
  handler: async ({ companyId, trip: snapshot, car, driver, nowMs }) => {
    if ([snapshot.companyId, car.companyId, driver.companyId].some((id) => id !== companyId)) {
      return fail(tripRejected, { reason: "foreign-company" });
    }
    if (snapshot.status !== "planned") return fail(tripRejected, { reason: "not-planned" });
    if (snapshot.carId !== null || snapshot.driverId !== null) {
      return fail(tripRejected, { reason: "already-assigned" });
    }
    if (car.availability !== "available") return fail(tripRejected, { reason: "car-unavailable" });
    if (driver.availability !== "available") {
      return fail(tripRejected, { reason: "driver-unavailable" });
    }
    if (!driver.active || driver.licenseValidUntilMs <= nowMs) {
      return fail(tripRejected, { reason: "driver-ineligible" });
    }
    if (snapshot.passengerCount > car.seats) {
      return fail(tripRejected, { reason: "insufficient-seats" });
    }
    return { ...snapshot, status: "assigned" as const, carId: car.carId, driverId: driver.driverId };
  },
});

