import { defineFunction, fail } from "@relkit/app/functions";
import { z, type InferOutput } from "@relkit/app/schema";
import { tripRejected } from "../errors.js";
import { id, status, trip } from "../schemas.js";

type TripStatus = InferOutput<typeof status>;
const transitions: Readonly<Record<TripStatus, readonly TripStatus[]>> = {
  planned: ["cancelled"],
  assigned: ["in_progress", "cancelled"],
  in_progress: ["completed"],
  completed: [],
  cancelled: [],
};

export default defineFunction({
  id: "trips.transition-trip",
  input: z.object({ companyId: id, trip, to: status }),
  output: trip,
  errors: [tripRejected],
  handler: async ({ companyId, trip: snapshot, to }) => {
    if (snapshot.companyId !== companyId) return fail(tripRejected, { reason: "foreign-company" });
    const hasAssignment = snapshot.carId !== null && snapshot.driverId !== null;
    const partialAssignment = (snapshot.carId === null) !== (snapshot.driverId === null);
    if (
      partialAssignment ||
      (snapshot.status === "planned" && hasAssignment) ||
      (["assigned", "in_progress", "completed"].includes(snapshot.status) && !hasAssignment)
    ) {
      return fail(tripRejected, { reason: "invalid-assignment-state" });
    }
    if (!transitions[snapshot.status].includes(to)) {
      return fail(tripRejected, { reason: "invalid-transition" });
    }
    return { ...snapshot, status: to };
  },
});

