import { expect, test } from "bun:test";
import { invokeFunction } from "@relkit/testing";
import companies from "@app/services/companies/service.js";

const onboarding = {
  companyId: "company-a",
  legalName: "  Fleet A  ",
  registrationNumber: "REG-A",
  ownerUserId: "owner-a",
};
const staff = {
  company: { companyId: "company-a", status: "active" as const },
  userId: "driver-user",
  role: "driver" as const,
  existingMemberUserIds: [] as string[],
