import { expect, test } from "bun:test";
import { invokeFunction } from "@relkit/testing";
import fleet from "@app/services/fleet/service.js";

const model = { companyId: "a", modelId: "model", make: "Toyota", name: "Hiace", seats: 12 };
const car = { companyId: "a", carId: "car", model, registrationPlate: " abc 123 ", odometerKm: 200 };
const registration = {
  companyId: "a",
  driverId: "driver",
  membership: { companyId: "a", userId: "user", role: "driver" as const, status: "active" as const },
  licenseValidUntilMs: 2_000,
  nowMs: 1_000,
};

test("fleet owns validated models and creates cars from a same-company model", async () => {
  expect(await invokeFunction(fleet.registerModel, model)).toEqual(model);
  const result = await invokeFunction(fleet.registerCar, car);
  expect(result).toEqual({
    companyId: "a", carId: "car", modelId: "model", registrationPlate: "ABC 123",
    seats: 12, odometerKm: 200, availability: "available",
  });
  expect(car.registrationPlate).toBe(" abc 123 ");
});

test("car registration rejects another company's model", async () => {
  await expect(invokeFunction(fleet.registerCar, {
    ...car, model: { ...model, companyId: "b" },
  })).rejects.toThrow("foreign-model");
});

test("models and cars reject invalid capacity and negative odometers", async () => {
  await expect(invokeFunction(fleet.registerModel, { ...model, seats: 0 })).rejects.toThrow();
  await expect(invokeFunction(fleet.registerCar, { ...car, odometerKm: -1 })).rejects.toThrow();
});

test("an active driver membership with a valid license becomes an available driver", async () => {
  await expect(invokeFunction(fleet.registerDriver, registration)).resolves.toEqual({
    companyId: "a", driverId: "driver", userId: "user", licenseValidUntilMs: 2_000,
    active: true, availability: "available",
  });
});

test("driver registration rejects foreign or inactive memberships and non-driver roles", async () => {
  await expect(invokeFunction(fleet.registerDriver, {
    ...registration, membership: { ...registration.membership, companyId: "b" },
  })).rejects.toThrow("foreign-membership");
  await expect(invokeFunction(fleet.registerDriver, {
    ...registration, membership: { ...registration.membership, status: "inactive" },
  })).rejects.toThrow("ineligible-membership");
  await expect(invokeFunction(fleet.registerDriver, {
    ...registration, membership: { ...registration.membership, role: "dispatcher" },
  })).rejects.toThrow("ineligible-membership");
});

test("a license expires exactly at its validity timestamp", async () => {
  await expect(invokeFunction(fleet.registerDriver, {
    ...registration, nowMs: 2_000,
  })).rejects.toThrow("expired-license");
});

