import { expect, test } from "bun:test";
import { invokeFunction } from "@relkit/testing";
import maintenance from "@app/services/maintenance/service.js";

const input = {
  companyId: "a", recordId: "record",
  car: { companyId: "a", carId: "car", odometerKm: 1_000 },
  odometerKm: 1_100, performedAtMs: 1_000, nowMs: 2_000, description: "Oil change",
};

for (const odometerKm of [1_000, 1_100]) {
  test(`maintenance accepts a non-decreasing odometer of ${odometerKm}`, async () => {
    expect(await invokeFunction(maintenance.recordMaintenance, { ...input, odometerKm })).toEqual({
      record: {
        companyId: "a", recordId: "record", carId: "car", odometerKm,
        performedAtMs: 1_000, description: "Oil change",
      },
      proposedCarOdometerKm: odometerKm,
    });
    expect(input.car.odometerKm).toBe(1_000);
  });
}

test("maintenance rejects a decreasing odometer", async () => {
  await expect(invokeFunction(maintenance.recordMaintenance, {
    ...input, odometerKm: 999,
  })).rejects.toThrow("decreasing-odometer");
});

test("maintenance rejects a foreign car and future records", async () => {
  await expect(invokeFunction(maintenance.recordMaintenance, {
    ...input, car: { ...input.car, companyId: "b" },
  })).rejects.toThrow("foreign-car");
  await expect(invokeFunction(maintenance.recordMaintenance, {
    ...input, performedAtMs: 2_001,
  })).rejects.toThrow("future-record");
});

test("maintenance validates negative and fractional odometers and blank descriptions", async () => {
