import { expect, test } from "bun:test";
import { invokeFunction } from "@relkit/testing";
import tracking from "@app/services/tracking/service.js";

const sample = {
  companyId: "a", car: { companyId: "a", carId: "car" },
  latitude: 24.7136, longitude: 46.6753, observedAtMs: 100_000, nowMs: 100_000,
};

test("fresh GPS positions return their car association and age", async () => {
  expect(await invokeFunction(tracking.validatePosition, sample)).toEqual({
    companyId: "a", carId: "car", latitude: 24.7136, longitude: 46.6753,
    observedAtMs: 100_000, ageMs: 0,
  });
});

test("coordinate extremes and the exact sixty-second freshness boundary are accepted", async () => {
  for (const [latitude, longitude] of [[-90, -180], [90, 180], [0, 0]] as const) {
    const result = await invokeFunction(tracking.validatePosition, {
      ...sample, latitude, longitude, nowMs: 160_000,
    });
    expect(result.ageMs).toBe(60_000);
  }
});

for (const [latitude, longitude] of [
  [-90.001, 0], [90.001, 0], [0, -180.001], [0, 180.001],
  [Number.NaN, 0], [0, Number.POSITIVE_INFINITY],
] as const) {
  test(`invalid GPS coordinates ${latitude}, ${longitude} are rejected`, async () => {
    await expect(invokeFunction(tracking.validatePosition, {
      ...sample, latitude, longitude,
    })).rejects.toThrow();
  });
}

test("GPS rejects stale and future samples with exact boundary failures", async () => {
  await expect(invokeFunction(tracking.validatePosition, {
    ...sample, nowMs: 160_001,
  })).rejects.toThrow("stale-sample");
  await expect(invokeFunction(tracking.validatePosition, {
    ...sample, observedAtMs: 100_001,
  })).rejects.toThrow("future-sample");
});

test("GPS rejects foreign cars and invalid timestamps", async () => {
  await expect(invokeFunction(tracking.validatePosition, {
    ...sample, car: { ...sample.car, companyId: "b" },
  })).rejects.toThrow("foreign-car");
  for (const observedAtMs of [-1, 1.5, Number.POSITIVE_INFINITY, Number.MAX_SAFE_INTEGER + 1]) {
    await expect(invokeFunction(tracking.validatePosition, { ...sample, observedAtMs })).rejects.toThrow();
  }
});

