import { expect, test } from "bun:test";
import { invokeFunction } from "@relkit/testing";
import trips from "@app/services/trips/service.js";

const planned = {
  companyId: "a", tripId: "trip", passengerCount: 3,
  status: "planned" as const, carId: null, driverId: null,
};
const assignment = {
  companyId: "a",
  trip: planned,
  car: { companyId: "a", carId: "car", seats: 4, availability: "available" as const },
  driver: {
    companyId: "a", driverId: "driver", active: true,
    availability: "available" as const, licenseValidUntilMs: 2_000,
  },
  nowMs: 1_000,
};

test("assignment returns the assigned trip without mutating or reserving its input", async () => {
  const before = structuredClone(assignment);
  expect(await invokeFunction(trips.assignTrip, assignment)).toEqual({
    ...planned, status: "assigned", carId: "car", driverId: "driver",
  });
  expect(assignment).toEqual(before);
});

for (const resource of ["trip", "car", "driver"] as const) {
  test(`assignment rejects a foreign-company ${resource}`, async () => {
    await expect(invokeFunction(trips.assignTrip, {
      ...assignment, [resource]: { ...assignment[resource], companyId: "b" },
    })).rejects.toThrow("foreign-company");
  });
}

test("assignment rejects unavailable resources, ineligible drivers, and insufficient seats", async () => {
  for (const availability of ["reserved", "in_trip", "in_maintenance"] as const) {
    await expect(invokeFunction(trips.assignTrip, {
      ...assignment, car: { ...assignment.car, availability },
    })).rejects.toThrow("car-unavailable");
  }
  for (const availability of ["reserved", "in_trip"] as const) {
    await expect(invokeFunction(trips.assignTrip, {
      ...assignment, driver: { ...assignment.driver, availability },
    })).rejects.toThrow("driver-unavailable");
  }
  await expect(invokeFunction(trips.assignTrip, {
    ...assignment, driver: { ...assignment.driver, active: false },
  })).rejects.toThrow("driver-ineligible");
  await expect(invokeFunction(trips.assignTrip, {
    ...assignment, nowMs: 2_000,
  })).rejects.toThrow("driver-ineligible");
  await expect(invokeFunction(trips.assignTrip, {
    ...assignment, car: { ...assignment.car, seats: 2 },
  })).rejects.toThrow("insufficient-seats");
});

test("assignment rejects reassignment and a planned trip already carrying resources", async () => {
  await expect(invokeFunction(trips.assignTrip, {
    ...assignment, trip: { ...planned, status: "assigned", carId: "car", driverId: "driver" },
  })).rejects.toThrow("not-planned");
  await expect(invokeFunction(trips.assignTrip, {
    ...assignment, trip: { ...planned, carId: "car" },
  })).rejects.toThrow("already-assigned");
});

const statuses = ["planned", "assigned", "in_progress", "completed", "cancelled"] as const;
const allowed = new Set(["planned:cancelled", "assigned:in_progress", "assigned:cancelled", "in_progress:completed"]);

for (const from of statuses) {
  for (const to of statuses) {
    test(`trip transition ${from} -> ${to}`, async () => {
      const snapshot = {
        ...planned, status: from,
        carId: from === "planned" ? null : "car",
        driverId: from === "planned" ? null : "driver",
      };
      const result = invokeFunction(trips.transitionTrip, { companyId: "a", trip: snapshot, to });
      if (allowed.has(`${from}:${to}`)) {
        await expect(result).resolves.toEqual({ ...snapshot, status: to });
      } else {
        await expect(result).rejects.toThrow("invalid-transition");
      }
    });
  }
}

test("transition rejects foreign ownership and inconsistent assignment snapshots", async () => {
  await expect(invokeFunction(trips.transitionTrip, {
    companyId: "b", trip: planned, to: "cancelled",
  })).rejects.toThrow("foreign-company");
  for (const snapshot of [
    { ...planned, status: "assigned" as const },
    { ...planned, carId: "car" },
    { ...planned, carId: "car", driverId: "driver" },
  ]) {
    await expect(invokeFunction(trips.transitionTrip, {
      companyId: "a", trip: snapshot, to: "cancelled",
    })).rejects.toThrow("invalid-assignment-state");
  }
});

test("assignment validates input before evaluating rules", async () => {
  await expect(invokeFunction(trips.assignTrip, {
    ...assignment, trip: { ...planned, passengerCount: 0 },
  })).rejects.toThrow();
});
